/* Original supplementary lessons. Shared KS2 foundations are not full year schemes. */
const EXPANSION_START=SCHOOL_LESSONS.length;
function XL(id,subject,title,years,explain,worked,mistake,tryIt,model,questions){SL(id,subject,title,years,explain,worked,mistake,tryIt,model,questions)}
XL('symmetry_more','Mathematics','Reflection symmetry: matching both sides',[3,4,5,6],
['A line of symmetry divides a shape into two parts that match exactly when folded along that line. It is not simply any line through the middle.','To reflect a point across a mirror line on squared paper, count its perpendicular distance from the line. Place its image the same distance on the other side. The reflected shape keeps its size.'],
['A point is two squares to the left of a vertical mirror line. Its image is two squares to the right, at the same height.','A non-square rectangle has two lines of symmetry: through the centres of opposite sides. Its diagonals are not symmetry lines.'],
'A diagonal does not automatically make matching halves. Check by imagining a fold.',
'On squared paper, draw a vertical mirror line and a three-square staircase beside it. Reflect each corner, join the images and explain how you checked the distances. Older pupils: compare the symmetries of a square and a non-square rectangle.',
'Each original corner and its image are equally far from the mirror line, on opposite sides. A square has four symmetry lines; a non-square rectangle has two.',
[['A point is 3 squares left of a vertical mirror line. Where is its reflection?','3 squares right at the same height','6 squares right','3 squares above','On the mirror line','Reflection places the point an equal distance on the other side.'],['How many lines of symmetry does a square have?','4','1','2','8','Two centre lines and two diagonals each make matching halves.'],['Does a reflected shape change size?','No','It doubles','It halves','Only its width changes','Reflection preserves size; the orientation is reversed.']]);
XL('coordinates_more','Mathematics','Coordinates: across first, then up',[4,5,6],
['A coordinate pair gives a position on a grid. In the first quadrant, start at the origin (0, 0). The first number tells you how far to move horizontally; the second tells you how far to move vertically.','We write coordinates in brackets, such as (4, 2). For a translation, move every vertex by the same amount in the same direction. The shape stays the same size and orientation.'],
['To plot (4, 2), move four units right and then two units up. Label that point A.','Translate A three units left and one unit up: (4 − 3, 2 + 1) = (1, 3).'],
'Swapping the numbers usually changes the position. Read the horizontal number first.',
'Draw axes from 0 to 6. Plot A(1,1), B(4,1) and C(1,3). Join the triangle, then move it one unit right and two up. Write the three new coordinates.',
'The translated vertices are A(2,3), B(5,3) and C(2,5). Corresponding vertices moved equally.',
[['Which number is the horizontal coordinate in (5, 2)?','5','2','7','0','The horizontal coordinate is written first.'],['Move (2, 3) two units right. What is the new point?','(4, 3)','(2, 5)','(0, 3)','(4, 5)','Only the horizontal position increases by two.'],['What changes during a translation?','Position','Side lengths','Angles','Shape size','Every point moves equally, preserving the shape.']]);
XL('negative_more','Mathematics','Negative numbers and changes in temperature',[4,5,6],
['Negative numbers lie below zero on a number line. Moving right increases the number; moving left decreases it. The minus sign is part of a negative number, such as −4.','To find a change that crosses zero, count the steps to zero and then beyond it. A temperature of −6°C is colder than −2°C, even though 6 is larger than 2.'],
['From −3°C to 2°C: three degrees to zero and two more above zero make a rise of 5°C.','From 1°C down by 4°C: 1 → 0 → −1 → −2 → −3. The new temperature is −3°C.'],
'Do not compare negative temperatures by ignoring their signs. Locate them on a number line.',
'Draw a number line from −6 to 6. Mark −4, −1 and 3. Find the rise from −4°C to 3°C and the temperature after 2°C falls by 5°C.',
'The rise is 7°C. After a fall of 5°C from 2°C, the temperature is −3°C. Show the individual steps.',
[['Which is colder?','−5°C','−1°C','0°C','3°C','−5 lies furthest left on the number line.'],['What is the rise from −2°C to 4°C?','6°C','2°C','−6°C','8°C','Count two steps to zero and four more to 4.'],['What comes immediately after −1 when counting upwards?','0','−2','1','−10','Counting upwards moves right towards zero.']]);
XL('poetry_more','English','Poetry: images, similes and reading aloud',[3,4,5,6],
['Poets choose words, sounds and line breaks to shape a reader’s experience. A poem does not have to rhyme. Read it aloud and notice where a pause helps the meaning.','A simile compares things using “like” or “as”. In “the moon is like a silver button”, the comparison helps us picture its round shape and pale shine. Explain the effect with evidence, rather than just naming a technique.'],
['Original lines: “The wind drums softly on the gate. / A leaf turns like a tiny boat.” The simile suggests a leaf moving and tilting on the wind.','The word “softly” makes the drumming seem gentle. Reading slowly can match that quiet mood. Other interpretations can work if supported.'],
'Rhyme alone does not make a good poem. Meaning and carefully chosen images matter too.',
'Write four lines about a place you know. Use one simile and one precise verb. Read the poem to someone, then explain one word choice. Older pupils: change a line break and discuss its effect.',
'Accept original images and an explanation linking a chosen word to its effect. Check that a simile compares two things meaningfully; do not grade a poem only by rhyme.',
[['Which sentence contains a simile?','The cloud floated like a pillow.','The cloud floated.','A cloud is overhead.','We saw clouds yesterday.','“Like a pillow” makes an explicit comparison.'],['Must every poem rhyme?','No','Yes, every line','Only poems about nature','Only poems read aloud','Poetry can use rhythm, images and other structures without rhyme.'],['Which response best explains a word choice?','“Whispered” makes the voice seem quiet.','It has nine letters.','The poet used a word.','It comes before a full stop.','It connects the word to the impression it creates.']]);
XL('speech_more','English','Direct speech: showing the speaker’s words',[3,4,5,6],
['Direct speech gives the exact words a character says. Inverted commas mark the spoken words. A reporting clause, such as “Maya said”, identifies the speaker.','In “Come inside,” Maya said, the comma sits inside the closing inverted comma. If the speech is a question, its question mark belongs inside instead. Begin a new paragraph when the speaker changes.'],
['“Where is my coat?” asked Sam. The question mark finishes Sam’s spoken question, so an extra comma is not needed.','Maya replied, “It is beside the door.” The reporting clause comes first; a comma introduces the spoken sentence.'],
'Inverted commas surround the speech, not the reporting clause.',
'Write a six-line conversation about a lost library book. Use at least two speakers, a question and a statement. Check speech punctuation and start a new paragraph for each speaker.',
'Check that the exact words spoken are enclosed, questions have a question mark inside, and each change of speaker begins a new paragraph. Accept consistent single or double inverted commas.',
[['What belongs inside inverted commas?','The exact words spoken','Only the speaker’s name','The whole story','Only the reporting verb','The punctuation marks the character’s actual words.'],['When should dialogue usually start a new paragraph?','When the speaker changes','After every word','Only at the end','After every adjective','Paragraphs help readers track different speakers.'],['Which punctuation ends the spoken question “Are you ready?”','A question mark inside the inverted commas','A comma outside only','No punctuation','An apostrophe','A question mark belongs to the spoken question.']]);
XL('nonfiction_more','English','Non-fiction: headings, key ideas and summaries',[3,4,5,6],
['Non-fiction can inform, explain or instruct. Headings indicate a section’s subject. A summary retells the most important ideas in fewer words; it is not a copy of every detail.','Original report: “School garden. Pupils planted beans in two tubs. Both tubs received the same amount of water. One stood in sunlight; the other was in a dark cupboard. The sunny plants grew green leaves. The dark-grown plants were pale.”'],
['A suitable heading is “Growing beans in different light conditions”. A summary is: pupils compared plants grown with and without light, and observed differences in leaf colour.','The report does not state the plants’ heights. We must not add a claim that one grew taller just because it seems likely.'],
'A heading guides a reader; it does not prove that every statement underneath is reliable.',
'Write a heading and a two-sentence summary of the report. Then list one observation and one question you would investigate next. Older pupils: identify a limitation of using only two tubs.',
'Include the difference in light and leaf colour without inventing height measurements. Possible next question: would repeated tubs show the same pattern? A small test does not settle every growing condition.',
[['What was deliberately different between the tubs?','Light conditions','Amount of water','Plant species','The school name','One tub was in sunlight and the other in darkness.'],['Which detail is not given in the report?','Plant height','Leaf colour','Use of beans','Two tubs','No height measurement is reported.'],['What is the aim of a summary?','To state the key ideas briefly','To add invented details','To copy every word','To list only punctuation','A summary selects the main information accurately.']]);
XL('persuasion_more','English','Persuasive writing: reasons, evidence and fairness',[5,6],
['Persuasive writing tries to influence a reader. A clear viewpoint is supported by relevant reasons and evidence. Emotional language may attract attention, but it does not replace a sound argument.','A balanced writer considers an objection and responds respectfully. A proposal for a book corner might acknowledge limited classroom space and suggest a small, movable shelf.'],
['Claim: our class should have a quiet reading corner. Reason: some pupils want a calm place during indoor break. Evidence could come from an actual class survey; do not invent survey figures.','Counterargument: there is little space. Response: trial a small corner for two weeks and ask the teacher to review its use.'],
'Saying that “everyone agrees” is not evidence unless you have actually checked the relevant group.',
'Write a short letter proposing an improvement at school. Include a viewpoint, two reasons, an objection and a respectful response. Label any information you would need to collect before making factual claims.',
'Look for a relevant audience, connected reasons and a genuine response to an objection. Opinions may differ. Reject invented statistics; allow proposals that are practical and respectful.',
[['Which would be useful evidence for a class preference?','A real class survey','An invented percentage','Repeating “obviously”','A louder voice','Evidence needs a source that can support the claim.'],['What is a counterargument?','A reasonable opposing point','The title of a letter','A spelling mistake','The writer’s signature','It is a point someone might raise against a proposal.'],['Which response is most respectful?','I understand the space concern; could we try a small shelf?','Only silly people disagree.','You must agree immediately.','There are no disadvantages.','It acknowledges the objection and offers a possible solution.']]);
XL('science_enquiry_more','Science','Working scientifically: fair comparisons and observations',[3,4,5,6],
['An investigation starts with a question that evidence can help answer. In a fair comparison, change the factor you are testing and keep other relevant conditions alike. Decide what you will observe or measure.','Repeating measurements can reveal variation. An unexpected result is a reason to check the method and record honestly, not to replace it with the number you wanted.'],
['Question: does a toy car travel further down a steeper ramp? Change ramp height; keep the same car, surface and release method. Measure the distance travelled from the ramp’s end.','Repeat each height three times. Write down all distances with units. Compare the results, explaining that other surfaces might give different distances.'],
'Changing the car and the height together makes it hard to know what caused a difference.',
'Plan this test on paper first. State what you will change, keep the same and measure. With an adult, use a low stable ramp away from feet. Record three trials at each of two heights. Older pupils: calculate a mean.',
'Change only height, measure distance consistently and record units. Discuss variation and a possible improvement. Do not require a predetermined outcome.',
[['What should change in the ramp comparison?','Ramp height','Car and surface and height','Only the car colour','The measuring unit each time','Height is the factor being investigated.'],['Why repeat measurements?','To see how results vary','To choose only the biggest value','To hide mistakes','To avoid recording units','Repeated trials help assess consistency.'],['What should you do with an unexpected reading?','Record it and check the method','Invent a better value','Delete every result','Claim the test is perfect','Honest recording allows the method and result to be examined.']]);
XL('light_year6_more','Science','Light travels in straight lines: seeing an object',[6],
['We see a luminous object when light from it enters our eyes. We see a non-luminous object, such as a book, when light reflects from it into our eyes. Our eyes do not send out seeing rays.','In a simple ray model, light travels in straight lines. An opaque object blocks light, producing a shadow where less light reaches a surface. A mirror changes the direction of reflected light.'],
['To see a book beside a lamp: lamp → book → eye. The book reflects some of the lamp’s light.','With a torch held still, move an opaque card between it and a wall. The card blocks some rays, so a shadow appears. Never look at the Sun or shine a torch into eyes.'],
'A mirror reflects light; it does not make its own supply of light.',
'Draw and label a lamp, a toy and an eye. Add arrows showing how the toy becomes visible. Explain why an opaque card can cast a shadow. Use an adult-supervised torch demonstration if available.',
'Arrows travel from the source to the toy and from the toy to the eye. The shadow is a region where the opaque card blocks the source’s light.',
[['Which route lets us see a non-luminous book?','Lamp → book → eye','Eye → book → lamp','Book → lamp → eye only','Eye → lamp → book','Light reflects from the illuminated book into the eye.'],['What does opaque mean?','Light does not pass through it','It makes light','It is always a mirror','It has no shadow','An opaque material blocks transmission of light.'],['What does a mirror do to incident light?','Reflects it','Creates all of it','Turns it into sound','Makes it stop existing','A mirror redirects light by reflection.']]);
XL('circuits_year6_more','Science','Circuits: comparing cells, bulbs and predictions',[6],
['An electric current needs a complete conducting loop. A cell supplies energy to the circuit; a bulb transfers energy to light and heating. A switch opens or closes a gap in the loop.','In otherwise comparable simple circuits, adding a suitable cell in series can make the same bulb brighter. Adding another identical bulb in series to the same supply generally makes each dimmer. Components must stay within their ratings.'],
['Compare a circuit with one cell and one bulb to one with two suitable cells and the same bulb. Keep the wires, bulb type and connections alike. Predict a brightness change, then check safely.','If the switch is open, the conducting loop is broken and the bulb goes out. Closing it completes the loop.'],
'A picture with a cell and bulb is not enough: check both connections form a complete loop.',
'Draw a complete cell-switch-bulb loop. Draw it again with an open switch. Explain a safe brightness comparison. Use only suitable low-voltage classroom equipment with an adult; never mains sockets or damaged batteries.',
'The closed loop connects both cell terminals through the bulb. An open switch interrupts the path. The comparison changes one factor and respects the equipment rating.',
[['What happens when a switch breaks the loop?','The bulb goes out','The bulb becomes a battery','The wire disappears','Current jumps any gap','An open circuit does not provide a continuous conducting path.'],['What should stay the same when comparing one and two suitable cells?','The bulb type','The number of cells','Every variable','Only the drawing title','Keeping the bulb alike makes the comparison more meaningful.'],['Which equipment is appropriate for a home demonstration?','Suitable low-voltage kit with an adult','A mains socket','A damaged battery','Bare mains wiring','Use age-appropriate low-voltage equipment and adult supervision.']]);
XL('history_change_more','History','History: change, continuity and a local place',[3,4,5,6],
['Change means something becomes different over time. Continuity means something remains similar. Historians compare evidence from different dates to investigate both.','A photograph can show visible details, but not everything about people’s lives. Check its date, place and purpose. Combine sources where possible and distinguish what you can see from what you infer.'],
['A 1920 photograph shows a bridge over a river. A modern photograph from the same place shows a wider bridge. The crossing continued, but its width changed.','We cannot count all the bridge’s daily users from one photograph. A dated traffic record could help answer that separate question.'],
'Old does not automatically mean unreliable, and a photograph does not answer every question.',
'With a parent, compare two dated pictures of a familiar place. List two visible changes, one continuity and a question neither picture answers. Older pupils: consider whether the viewpoints are comparable.',
'Accept details supported by the images. Separate observation from inference and identify missing evidence. Do not assume the entire town changed because one street changed.',
[['What does continuity mean in history?','Something stays similar over time','Nothing can ever change','Only a photograph','The newest date','Continuity identifies features that persist.'],['Which helps compare two photographs?','Checking dates and locations','Ignoring their viewpoints','Assuming all photos are today','Counting only colours','Date and location provide essential context.'],['Can one photograph show daily traffic totals?','Usually not','Always','Only if it is old','Only if it is colourful','A single moment does not record a whole day.']]);
XL('history_periods_more','History','Prehistory: Stone Age, Bronze Age and Iron Age',[3,4,5,6],
['Prehistory refers to the period before written records for the people and place being studied. Archaeologists use surviving evidence such as tools, bones and buildings.','In a broad sequence for Britain, the Stone Age came before the Bronze Age, followed by the Iron Age. These names reflect important tool materials, but people continued using other materials too. Changes happened gradually and at different times in different places.'],
['A stone tool can help us investigate how people worked, but without further evidence we cannot know its owner’s name.','Place Stone Age → Bronze Age → Iron Age on a simple sequence. The order does not mean that everyone instantly stopped using stone when bronze became available.'],
'Not all evidence survives. The absence of a written record does not mean people had no stories or knowledge.',
'Create a three-part timeline in this order. Draw a possible tool material for each period. Write one question an object might help answer and one question it probably cannot answer alone.',
'Check the sequence and sensible limits of evidence. A tool may suggest a task or material, but usually not the exact name or feelings of its maker. Older pupils can investigate a dated local archaeological site with a parent.',
[['Which comes first in this broad British sequence?','Stone Age','Iron Age','Bronze Age','Victorian period','The Stone Age precedes the Bronze and Iron Ages.'],['Who studies material remains of past societies?','An archaeologist','A weather forecaster only','A referee','A contemporary traffic warden','Archaeologists investigate surviving objects and sites.'],['Does a bronze tool prove that nobody used stone then?','No','Yes, everywhere','Yes, on every continent','Only in winter','Materials overlap; period names are broad descriptions.']]);
XL('rivers_more','Geography','Rivers: source, tributary, channel and mouth',[3,4,5,6],
['A river flows downhill through a channel under gravity. Its source is where it begins; its mouth is where it enters the sea, a lake or another river. A tributary is a smaller stream or river that joins a larger one.','Flowing water can wear away material (erosion), carry it (transportation) and drop it (deposition). These processes can change a river landscape. Not every river is straight or the same width throughout.'],
['On a map, follow a small stream from high ground until it joins a larger river. That joining stream is a tributary.','If moving water loses enough energy to carry some sediment, material may be deposited. Erosion and deposition can occur in different parts of a river system.'],
'A source is not the same as a mouth. Use the direction of flow to distinguish them.',
'Draw an imaginary river from hills to sea. Label source, tributary, main channel and mouth. Add arrows for flow. Older pupils: label a place where sediment might be deposited and explain your reasoning.',
'Water arrows should follow a downhill route towards the mouth. A tributary joins the main channel. Accept a plausible explanation of sediment being dropped as conditions change. No waterside visit is required.',
[['What is a tributary?','A stream joining a larger river','The sea itself','A mountain summit only','A compass needle','Tributaries contribute flow to a larger river.'],['What is deposition?','Dropping carried material','Making all water vanish','Naming a river','Measuring temperature','Deposition leaves transported sediment behind.'],['What makes river water flow downhill?','Gravity','The map title','The north arrow','The river name','Gravity drives downhill movement.']]);
XL('climate_more','Geography','Weather, climate and comparing places',[3,4,5,6],
['Weather describes conditions at a particular place and time: for example, today’s rain, temperature and wind. Climate describes typical patterns over many years.','A single hot day does not show a place’s entire climate. Compare long-term information, location and seasons. A climate graph can show typical monthly temperature and rainfall, with the units on its axes.'],
['“It is raining this afternoon” describes weather. “This region usually has dry summers” describes a climate pattern.','If two places have average January temperatures of 5°C and 20°C, the second is warmer in that dataset. We still need other months to discuss the annual pattern.'],
'Do not decide the climate of an entire country from one day or one town.',
'Record the weather outside your window for five days without taking risks. Describe what changes. Explain why five days cannot establish the full climate. Older pupils: compare two long-term climate graphs from a reliable atlas.',
'Use dated observations and relevant units. A short weather diary describes those days; climate requires much longer records. Graph comparisons should mention both place and month.',
[['Which statement describes weather?','It is windy this morning.','The region usually has wet winters.','Long-term summers are dry.','Average conditions over decades','Weather concerns current or short-term conditions.'],['What is climate based on?','Patterns over many years','One afternoon only','A single holiday photo','A compass direction alone','Climate summarises long-term conditions.'],['What should you check on a rainfall graph?','The units and time period','Only the colour','Only the page number','Whether it has a photograph','Units and dates tell us what the values mean.']]);
XL('computing_repeat_more','Computing','Programming: repetition and debugging a pattern',[3,4,5,6],
['A sequence runs instructions in order. Repetition, or a loop, repeats a set of instructions. It makes a repeated pattern easier to describe and change.','Debugging means finding and fixing an error. Predict what a program will do, trace one step at a time, and compare the result with your intention. A program may run without doing what you meant.'],
['For a square drawing: repeat four times [move 50 steps; turn right 90 degrees]. There are four equal sides and four quarter-turns.','If the loop repeats only three times, the final side is missing. Changing the turn to 45 degrees also changes the path; test one correction at a time.'],
'A repeat count tells you how many times to run the whole enclosed set, not just its first instruction.',
'Write an unplugged program to draw a square on paper. Trace it with your finger. Introduce one deliberate error and ask a partner to find it. Older pupils: use a repeat loop to draw two squares of different sizes in a school-approved tool.',
'Expect four moves with four 90-degree turns. The explanation identifies a specific mismatch and a correction. A screen is optional; paper tracing demonstrates the idea.',
[['How often does repeat 4 [clap; tap] clap?','4 times','1 time','8 times','0 times','The complete two-action sequence repeats four times.'],['What is debugging?','Finding and fixing errors','Deleting all programs','Only making pictures','Ignoring an unexpected result','Debugging compares intended and actual behaviour.'],['Which turn helps draw a square?','90 degrees','45 degrees','10 degrees','180 degrees each corner','A square has four right-angle changes of direction.']]);
XL('computing_data_more','Computing','Data: collecting, organising and checking information',[3,4,5,6],
['Data is recorded information. Before collecting it, decide what question you want to answer, which categories you will use and how you will record each response.','A table organises data, while a chart can make comparisons easier. Check that categories are clear and totals match. Collect only information needed for the activity; do not publish classmates’ personal details.'],
['Five toy blocks are red, blue, red, green and red. A frequency table gives red 3, blue 1, green 1. The frequencies total 5.','A bar chart with a zero baseline and equally spaced counts can compare these categories. Label the categories and the count axis.'],
'A chart can be misleading if its labels, scale or data do not match the question.',
'Sort ten household objects by a safe visible feature such as colour. Make a tally and frequency table, then a labelled bar chart. Older pupils: explain what the chart cannot tell you about a different collection.',
'The frequencies should total the number of objects. Bars and labels should agree with the table. Do not infer preferences or general facts about everyone from a small set of objects.',
[['Red, blue, red, green, red: how many are red?','3','2','4','5','Count the red entries individually.'],['What should the category frequencies total?','The number of recorded objects','Always 100','Only the biggest category','The number of colours squared','Each object is counted once in this sorting task.'],['Which information is needed for an anonymous colour count?','The colour choices only','Home addresses','Passwords','Full dates of birth','Collect only data relevant to the question.']]);
XL('art_colour_more','Art & Design','Colour mixing: testing a paint palette',[3,4,5,6],
['Artists test colours to choose effects. In a basic school paint model, red, yellow and blue are primary colours. Mixing pairs can make secondary colours such as orange, green and purple. Actual results depend on the paints and proportions.','Adding white usually makes a lighter tint. Test a small amount first and record the mixture. A warm or cool palette can suggest a mood, but people may respond differently to the same colour.'],
['Mix a little yellow paint into blue and observe a green mixture. Try a different proportion and compare the result.','Make a colour strip with blue, blue plus a little white, and blue plus more white. Label the mixtures so another person could try them.'],
'This is a paint-mixing model. Coloured light uses different mixing rules.',
'With washable art materials and an adult’s agreement, make three labelled colour mixtures. Choose two for a picture showing a mood. If no paints are available, compare coloured pencil layering instead.',
'Assess careful testing and an explanation of choices, not one “correct” mood. Record material and proportions approximately. Keep art materials away from mouths and wash hands afterwards.',
[['In a basic paint model, blue and yellow can make which colour?','Green','Orange','Pink','White','Blue and yellow pigments are commonly used to mix green.'],['What is a tint usually made by adding?','White','A ruler','Only black','Waterproof glue','White lightens a colour to make a tint in this model.'],['Why label colour experiments?','To remember and compare mixtures','To make all pictures identical','To avoid observation','To prove everyone feels the same','Records help an artist repeat or alter a mixture.']]);
XL('art_collage_more','Art & Design','Collage: texture, composition and explaining choices',[3,4,5,6],
['A collage combines pieces of material into an artwork. Texture is how a surface feels or appears to feel. Composition describes how parts are arranged.','Artists can try different arrangements before fixing pieces in place. Repeating a shape may create a pattern; changing its size or colour may draw attention to one area. There is more than one successful design.'],
['For an imaginary garden, use smooth scrap paper for a path and torn textured paper for leaves. Arrange them loosely first.','Move one large flower to the foreground. Explain how its size makes it stand out rather than saying it is the only correct arrangement.'],
'Adding more materials does not automatically improve a composition. Choose materials for a reason.',
'Create a small paper collage from clean scraps. Plan two arrangements, choose one and explain a texture and a placement decision. Ask an adult about scissors or glue; tearing paper is a valid alternative.',
'Look for purposeful choices, experimentation and respectful evaluation. Ask what the child would keep and what they would change; do not require copying a model.',
[['What is composition?','The arrangement of parts','Only the price of paper','A musical note only','The glue brand','Composition concerns how visual elements are placed.'],['What can textured material add?','A surface quality or its appearance','A guaranteed correct answer','Only extra weight','A compulsory colour','Texture may be felt physically or suggested visually.'],['When is it useful to try arrangements?','Before fixing pieces down','Only after throwing them away','Never','Only after framing','Loose arrangements make experimentation easier.']]);
XL('dt_structures_more','Design & Technology','Structures: folding, strength and a fair test',[3,4,5,6],
['A structure supports a load. Its material, shape and joins affect how it behaves. Folding paper changes its shape and can make it resist bending differently without adding another material.','A design test should match the purpose and compare fairly. Use the same span and similar loading method when comparing two paper bridges. Record failure honestly so you can improve the design.'],
['Bridge A is a flat strip of paper; bridge B is a similar strip folded into a channel. Place each across the same small gap.','Add identical light counters one at a time at the centre. Record how many each holds before bending substantially. Do not use heavy loads or test where items could fall on someone.'],
'One successful test does not prove a design is strongest under every possible load.',
'Sketch two paper bridge designs. With adult help, test them over a low gap using light counters. Record the span, load and what changed. Improve one feature and retest.',
'Compare designs under similar conditions. Accept any honestly recorded outcome. A useful evaluation links a change, such as a folded edge or stronger join, to an observed result.',
[['What is a load?','Something a structure supports','Only a paint colour','A page title','A type of music','Loads place demands on a structure.'],['What should stay alike in a bridge comparison?','The gap between supports','Every design feature','The result you hope for','Only the bridge names','Equal spans make this comparison fairer.'],['What is a useful next step after a weak test result?','Improve a feature and retest','Hide the result','Claim success anyway','Add unsafe heavy objects','Testing informs design improvements.']]);
XL('dt_food_more','Design & Technology','Food design: a safe, balanced snack plan',[3,4,5,6],
['Designing food starts with the person who will eat it and their needs. Consider preferences, allergies, ingredients, cost and the equipment available. A range of foods contributes different nutrients.','Food preparation needs clean hands, clean equipment and appropriate adult help. Check allergies before choosing ingredients. Cooking or cutting methods must suit the child and the equipment.'],
['Brief: design a simple snack for a family member. Ask about allergies first. Compare a fruit-and-yogurt idea with a vegetable-and-hummus idea using ingredients the household can safely eat.','A labelled plan lists ingredients, equipment and an adult-supervised method. Evaluation asks whether the snack met the agreed needs, not just whether it looked colourful.'],
'An ingredient being healthy for one person does not make it safe for somebody with an allergy.',
'Plan a snack on paper with a parent. Name the intended eater, safe ingredients and hygiene steps. Make it only with permission and supervision. Older pupils: estimate the cost and suggest a change after feedback.',
'Prioritise allergy checks, hygiene and a suitable method. Accept different balanced choices; use the household’s dietary needs rather than insisting on one food.',
[['What should be checked before choosing ingredients for someone?','Allergies and dietary needs','Only plate colour','Only the longest ingredient name','Whether a quiz was passed','The eater’s needs influence safe food design.'],['What is a sensible hygiene step?','Wash hands before preparing food','Use dirty utensils','Touch food after handling rubbish','Ignore work surfaces','Clean hands and equipment reduce contamination.'],['What should an evaluation compare the snack with?','The agreed design needs','An unrelated toy','Only its photograph size','The alphabet','Evaluation checks how well the design meets its purpose.']]);
XL('music_pitch_more','Music','Pitch and melody: higher, lower and musical phrases',[3,4,5,6],
['Pitch describes how high or low a sound is. It differs from volume, which describes loudness. A melody is an organised sequence of pitches, often grouped into phrases.','You can represent a simple tune using a rising or falling line before learning formal notation. Listen, sing or hum comfortably, and compare the direction of the notes. Loudness does not tell you which pitch is higher.'],
['Hum a comfortable note and then a slightly higher one. Draw a line rising from left to right to show the change.','Make a short phrase that rises twice and then returns to its first note. Repeat it softly; the pitch pattern can stay the same when volume changes.'],
'A louder sound is not necessarily higher in pitch.',
'Create a short comfortable humming phrase or use a safe classroom instrument. Draw a pitch contour and ask someone to follow it. Older pupils: create a contrasting answering phrase. Keep volume comfortable.',
'Look for a connection between the sound and the drawn rise/fall. Accept different melodies. Do not demand a loud voice or a particular singing range.',
[['Pitch tells us which quality?','How high or low a sound is','How expensive an instrument is','Only its loudness','How long the lesson is','Pitch and loudness are separate sound qualities.'],['Can a tune be played more softly without changing its notes?','Yes','No','Only on paper','Only if it has no rhythm','Volume can change while the sequence of pitches stays alike.'],['What can a rising line represent?','Pitch moving higher','A compulsory increase in volume','Silence only','The instrument’s weight','A contour line can show pitch direction.']]);
XL('music_listening_more','Music','Listening and composing: tempo, dynamics and structure',[3,4,5,6],
['Tempo describes musical speed. Dynamics describe loudness and changes in loudness. Structure is how sections are organised. These choices can influence the character of a piece.','In an ABA structure, an opening section A is followed by a different section B and then a return of A. Listen for repeated ideas rather than assuming every new instrument starts a completely new section.'],
['Clap A as four steady beats. Make B a contrasting short-long pattern. Return to A to create ABA.','Perform the whole pattern more slowly. That changes tempo. Perform it more softly at the same speed to change dynamics instead.'],
'Fast and loud are not the same instruction; a fast piece can be quiet.',
'Create an ABA piece using body percussion at a comfortable volume. Draw a symbol for each section. Perform it twice: once changing tempo and once changing dynamics. Explain the difference.',
'Expect a recognisable return of A and a contrasting B. The child should distinguish a speed change from a loudness change. Parent checks practical performance as well as quiz answers.',
[['What does tempo describe?','Speed','Loudness only','Instrument colour','Number of listeners','Tempo is how quickly the music moves.'],['Which sequence returns to the opening after contrast?','ABA','ABC','AAA only','BBB','ABA repeats A after a contrasting B.'],['What do dynamics describe?','Loudness and its changes','Only pitch names','The page number','Instrument price','Dynamic choices include softer and louder playing.']]);
XL('pe_games_more','Physical Education','Games: passing, space and cooperation',[3,4,5,6],
['In a team game, moving into space can give a teammate a safe passing option. Looking before passing helps you judge direction, distance and whether the receiver is ready.','Cooperation means following agreed rules, communicating respectfully and including others. A useful practice aims at control and decision-making, not only speed or winning. Adapt the activity to the child’s ability and comfort.'],
['With an adult in a clear space, roll a soft ball gently towards a partner’s hands. Wait until they are ready before releasing it.','For a three-person task, the player without the ball moves to a clear spot. The ball holder chooses a safe pass rather than forcing it through a crowded space.'],
'A powerful pass is not automatically a good pass. It should be controllable and safe for the receiver.',
'Use a soft ball or rolled socks in a clear safe area with an adult. Complete five controlled rolls or passes, then change distance slightly. Seated passing is an alternative. Stop if uncomfortable; never aim at faces.',
'Observe readiness, controlled movement and respectful communication. Let success mean improved control at an appropriate distance. The quiz checks decisions, not physical competence.',
[['What should you check before passing?','That the receiver is ready and the space is safe','Only who is winning','Whether the ball is the hardest possible','Whether you can throw at a face','Readiness and a safe route support control.'],['Why move into space?','To offer a passing option','To hide from teammates','To break every rule','To guarantee a score','Clear space can make a pass more achievable.'],['What matters in cooperative practice?','Including others and following agreed rules','Blaming every mistake','Always being fastest','Ignoring ability differences','Cooperation supports safe shared participation.']]);
XL('pe_sequences_more','Physical Education','Movement sequences: control, levels and reflection',[3,4,5,6],
['A movement sequence links actions in an intentional order. Actions may use different levels, directions and shapes. Smooth transitions connect them while maintaining control.','Practise slowly in a clear space with adult guidance. Choose comfortable movements and adapt them as needed. Performance improves through observation and thoughtful changes rather than risky tricks.'],
['A simple sequence might be reach upwards → step sideways → pause in a comfortable standing shape. The pause helps show control.','Try changing the direction of the step while keeping the other actions alike. Explain how the sequence looks or feels different.'],
'Harder or higher movements are not always better. Safety, control and clear choices matter.',
'Create three safe actions and practise the transitions. Show a parent, describe one thing that worked and make one small improvement. A seated sequence using arms and gentle turns is equally valid. Avoid flips, raised equipment or painful stretches.',
'Assess a clear order, controlled transitions and a reasoned improvement. Use the child’s comfortable range. A quiz cannot assess movement skill on its own.',
[['What is a transition?','The link between actions','Only the final pose','A scoreboard','A piece of raised equipment','Transitions connect movements into a sequence.'],['What should guide your choice of movements?','Safety and comfortable control','The biggest possible risk','Pain','Copying a difficult trick immediately','Choose appropriate movements and adapt them.'],['Which is a useful reflection?','My pause helped me balance; I will make the next step slower.','Everything must be perfect.','Only the fastest move counts.','I should ignore discomfort.','It identifies an observation and a practical improvement.']]);
XL('french_numbers_more','Languages','French: numbers one to ten and asking how many',[3,4,5,6],
['This is a French sample lesson. Use the language and vocabulary taught by your school; do not treat French as a requirement if the class learns another language.','French numbers one to ten are un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix. Written forms help us recognise words, but listening to a teacher or reliable recording is important for pronunciation. “Combien ?” asks “How many?”'],
['Count three pencils: un, deux, trois. Answer “trois” when asked how many there are.','Match cinq to 5 and dix to 10. Practise recognising them in a different order, not just reciting the whole list.'],
'English letter sounds do not always produce French pronunciation. The app’s English read-aloud is not a French pronunciation model.',
'Make number cards 1–10 and matching French word cards. Pair them, then count a small set of objects. Ask a parent to use school-approved French audio if available. Older pupils: write three number sequences with a missing value.',
'Check accurate number-word matching. Use school audio or teacher feedback for spoken pronunciation; a multiple-choice score does not assess speaking.',
[['Which French word means three?','trois','cinq','neuf','dix','Trois corresponds to 3.'],['What number is cinq?','5','2','8','10','Cinq means five.'],['What does “Combien ?” ask here?','How many?','What colour?','Where is the school?','What is your name?','Combien asks about quantity.']]);
XL('french_colours_more','Languages','French: recognising colours and a simple preference',[3,4,5,6],
['In this French sample, rouge means red, bleu means blue, vert means green and jaune means yellow. Listen to school audio to connect each written form with its sound.','“J’aime le bleu” means “I like blue”. A preference is your own opinion. When French colour words describe nouns, their forms may change to agree with the noun; this introductory lesson focuses on colour labels and the model sentence.'],
['Show a blue card and match it with bleu. Show a yellow card and match it with jaune.','Choose a colour you like and use the matching model: “J’aime le rouge” or “J’aime le bleu”. Recognise the words rather than guessing from card position.'],
'Do not assume a colour word has the same form in every French phrase. Follow your school’s model when describing nouns.',
'Make four labelled colour cards. Shuffle them and match the labels. Use one model preference sentence and illustrate it. Older pupils: find a teacher-approved example of a colour adjective agreeing with a noun.',
'Check the four labels and a suitable model sentence. Assess pronunciation using school audio or a knowledgeable speaker, not the English speech button. Use another school-taught language instead if appropriate.',
[['Which colour is jaune?','Yellow','Blue','Red','Green','Jaune is the French word for yellow.'],['Which word means blue?','bleu','rouge','vert','jaune','Bleu means blue in this colour-label context.'],['What does “J’aime le rouge” express?','I like red.','I have three pencils.','Where is the book?','It is raining.','J’aime expresses liking in this model sentence.']]);
XL('re_questions_more','Religious Education','RE: beliefs, evidence and respectful questions',[3,4,5,6],
['Religious education explores religious and non-religious worldviews. People within the same tradition may practise or interpret ideas differently. A respectful question invites a person to explain without assuming everyone agrees.','Distinguish an observation from an interpretation. Seeing a building’s features is different from knowing what those features mean to its community. Use the school’s agreed RE syllabus and reliable accounts from people in the tradition.'],
['Observation: a place of worship has a space where people gather. Question: “How is this space used by your community?” A community member can help explain its meaning.','Instead of “Do all people in your religion do exactly this?”, ask “Is this a practice in your community, and are there different approaches?”'],
'One person’s experience does not represent every member of a religion or worldview.',
'Choose a belief or community topic currently taught at school. Write two open questions, identify one reliable source and separate one observed detail from an interpretation. Older pupils: compare two accounts without deciding that every difference is a mistake.',
'Look for respectful wording, recognition of diversity and an appropriate source. Assess understanding, not the child’s own belief or agreement with a tradition.',
[['Which question is most open and respectful?','What does this practice mean to your community?','Why must everybody agree with me?','Why are all your beliefs identical?','Can I ignore your explanation?','It invites explanation without imposing an assumption.'],['Does one person represent every member of a tradition?','No','Always','Only if they speak loudly','Only if they own a book','Beliefs and practices can vary within communities.'],['What should RE assessment focus on here?','Understanding and respectful explanation','Having one required personal belief','Changing someone’s religion','Choosing the loudest opinion','Learning about worldviews does not require adopting them.']]);
XL('re_community_more','Religious Education','Sikhism: langar, service and community',[3,4,5,6],
['A gurdwara is a Sikh place of worship and community gathering. Langar is a community kitchen and shared meal associated with gurdwaras, open to people irrespective of background.','Seva means selfless service. Volunteers may help prepare, serve or clear the meal. Langar can express equality and service, although the details of an individual visit depend on the community’s arrangements.'],
['A volunteer serving food can explain the link between an action and the value of service. We should not assume the person receives payment for that volunteering.','When learning about langar, ask how the community welcomes visitors and what respectful practices visitors follow. A visit requires family/school planning, not an unaccompanied trip.'],
'Learning one practice does not tell us everything about every Sikh person’s life.',
'Draw a simple community-meal scene and label two ways people might help. Explain the connection with equality or service. Compare with a community activity you know, recognising both similarities and differences.',
'Expect an accurate connection between langar, welcome and service. Do not assess personal belief. Check details of any planned visit with the host community and school.',
[['What is a gurdwara?','A Sikh place of worship and community gathering','A river source','A musical speed','A type of computer','A gurdwara has religious and community roles.'],['What is langar?','A community kitchen and shared meal','A history timeline','A colour mixture','A type of battery','Langar is associated with welcoming and feeding people in community.'],['Which value is linked with seva?','Selfless service','Winning every competition','Keeping all help secret forever','Only buying expensive things','Seva concerns service to others.']]);
XL('pshe_online_more','PSHE / Relationships','Online choices: privacy, pressure and getting help',[3,4,5,6],
['Online messages can create pressure to share information or act quickly. Private details include addresses, passwords and information about someone else. A message or friendly profile is not proof of who is behind it.','If something is worrying or asks for private information, pause and tell a trusted adult. You do not have to reply to an uncomfortable message. An adult can help with reporting or blocking through the service’s tools.'],
['A game message promises a prize if you send a password. Do not send it. Close or pause the interaction and show a trusted adult.','If you shared something by mistake, ask for help promptly. Adults can help reduce the harm; embarrassment should not stop you seeking support.'],
'A person asking you to keep a worrying interaction secret is not a reason to handle it alone.',
'Write or role-play a safe response to a fictional prize message. Name two trusted adults and describe how to reach one. Do not use real passwords, addresses or screenshots of private conversations in the app.',
'Look for pausing, not sharing private details, and seeking help. A child is not to blame for someone else’s manipulative message. Discuss practical trusted adults with the family.',
[['A message asks for your password to give you a prize. What should you do?','Do not share it; tell a trusted adult','Send it immediately','Post it publicly','Give a friend’s password','Passwords are private; the prize claim is not proof of trust.'],['What if you shared something by mistake?','Ask a trusted adult for help','Never tell anyone','Send more private details','Pay to hide it','Prompt support can help address a mistake.'],['Does a friendly profile prove someone’s identity?','No','Always','Only with a colourful picture','Only in a game','Profiles can be misleading.']]);
XL('pshe_choices_more','PSHE / Relationships','Everyday money: needs, wants and a simple budget',[3,4,5,6],
['A need is something important for living and wellbeing; a want is something you would like. Context matters, so discuss examples rather than judging people’s choices. A budget is a plan for a limited amount of money.','If you spend part of a budget, less remains for other choices. Compare costs, check the total and think about saving. Advertising tries to influence choices, but a persuasive advert does not make an item necessary.'],
['For a pretend craft activity you have £5. Paper costs £2 and pencils cost £2, leaving £1. Decorations cost £2, so all three together would exceed the budget.','You might use clean scrap paper and save money for another item. Explain the trade-off rather than assuming the most expensive choice is best.'],
'Being able to buy one item does not mean you can afford every item on the list.',
'Make a pretend £6 plan for a drawing activity using three fictional prices you choose. List what you would buy and what you would postpone. Older pupils: compare two plans and explain an advertising claim to check.',
'Totals must stay within £6 unless the child clearly identifies an overspend. Accept different priorities with sensible reasons. No real payment or personal financial information is needed.',
[['A £5 budget buys £2 paper and £2 pencils. What remains?','£1','£2','£3','£4','£5 − £2 − £2 = £1.'],['What is a budget?','A plan for money available','A promise to buy everything','Only a bank password','An advert','Budgeting matches choices to limited resources.'],['Does an advert prove an item is a need?','No','Always','Only if colourful','Only on television','Advertising can influence wants; it does not establish necessity.']]);
const SUBJECT_COVERAGE_NOTES={Mathematics:'Selected number, calculation, fractions, measurement, geometry and data topics. Other year-specific objectives remain.',English:'Selected grammar, comprehension and writing topics. A full reading, spelling and writing sequence remains.',Science:'Selected science topics and enquiry. Coverage varies by year and is not a complete science scheme.',History:'Historical evidence, change and prehistory foundations. Local history and the school’s chosen historical periods remain.',Geography:'Maps, rivers and climate foundations. Named regional studies, fieldwork and wider physical geography remain.',Computing:'Algorithms, repetition, data and safety foundations. Practical projects, networks and wider programming remain.','Art & Design':'Drawing, colour and collage foundations. Wider artists, media and sustained projects remain.','Design & Technology':'Design cycle, structures and food planning foundations. Mechanisms, textiles and wider making remain.',Music:'Pulse, rhythm, pitch and structure foundations. Instrumental learning, notation and a wider listening repertoire remain.','Physical Education':'Movement and games concepts with gentle practical tasks. Swimming and broader PE need appropriate teaching and facilities.',Languages:'French sample foundations only. Match the school’s actual foreign language and course.','Religious Education':'Selected worldview and community topics. Follow the school’s agreed RE syllabus.','PSHE / Relationships':'Selected friendship, online safety and money choices. The school’s full relationships and health sequence remains.'};
function coveragePanel(){return `<details class="coverage-panel"><summary>Subject coverage · what is taught here and what remains</summary><p>This Year ${schoolYear()} library includes ${availableLessons().length} short original lessons. A subject being present does not mean its full yearly syllabus is taught. Shared KS2 lessons are foundations for consolidation, not four separate year courses.</p><div class="coverage-table"><table><caption>Built-in teaching coverage for the selected year</caption><thead><tr><th scope="col">Subject</th><th scope="col">Lessons</th><th scope="col">Coverage and remaining work</th></tr></thead><tbody>${Object.entries(SUBJECT_COVERAGE_NOTES).map(([s,n])=>`<tr><th scope="row">${E(s)}</th><td>${availableLessons().filter(l=>l.subject===s).length}</td><td>${E(n)}</td></tr>`).join('')}</tbody></table></div><p>Use the same topic and vocabulary taught at school. For more teaching, open the year’s subject list and choose the matching subject and unit.</p>${link(OAK_YEARS[pid()],'Find further year and subject lessons at Oak')}${link(links.curriculum,'Official primary curriculum')}</details>`}
const beforeCoverageLearning=schoolLearning,beforeCoverageLesson=schoolLesson;
schoolLearning=function(){return beforeCoverageLearning().replace('<div class="card">',coveragePanel()+'<div class="card">')};
schoolLesson=function(){let html=beforeCoverageLesson(),l=availableLessons().find(l=>l.id===schoolLessonId);if(l?.years.length===4)html=html.replace('<h1>',`<p class="shared-note">Shared KS2 foundation · adapt the written task with a parent to match the class topic. Not a complete year-specific unit.</p><h1>`);return html};

const beforeCoverageSettings=settings,beforeCoverageRender=render;
settings=function(){return `<section class="card"><h2>App version and updates</h2><p>Build ${RELEASE} · ${SCHOOL_LESSONS.length} built-in lessons across all year views. The selected year shows only its available lessons.</p><p>After uploading a new GitHub release, check for updates here. Save notes before reloading. This checks app files, not your personal progress.</p>${btn('Check for app updates','checkupdate')} ${btn('Reload saved app','reloadapp')}<p id="appUpdateStatus" role="status"></p></section>`+beforeCoverageSettings()};
render=function(){beforeCoverageRender();document.querySelectorAll('[data-action="checkupdate"]').forEach(el=>el.onclick=async()=>{const status=$('appUpdateStatus');if(!navigator.serviceWorker){status.textContent='This browser has no app cache. Reload after the host finishes publishing.';return}try{const registration=await navigator.serviceWorker.getRegistration();if(!registration){status.textContent='No offline cache is registered. Reload after publishing.';return}await registration.update();status.textContent='Update check requested. If new files become ready, save your work and reload. If none are available, confirm the GitHub deployment has finished.'}catch(e){status.textContent='Could not check updates. Check your connection and try again.'}});document.querySelectorAll('[data-action="reloadapp"]').forEach(el=>el.onclick=()=>window.location.reload())};
if(navigator.serviceWorker?.addEventListener)navigator.serviceWorker.addEventListener('controllerchange',()=>{$('notice').textContent='Updated app files are ready. Save any unfinished work, then reload this page to use them.'});
render();
